'use strict';
let analystTargetData=null,analystTargetBusy=false,analystTargetChecked=0,analystTargetLimit=8;
function renderAnalystTargets(){
 const host=document.querySelector('#analystTargets');if(!host)return;
 const d=analystTargetData,rows=(d?.items||[]).filter(x=>!dailySymbolFilter||x.ticker===dailySymbolFilter);
 const num=n=>Number.isFinite(n)?signed(n):'—';
 host.innerHTML=`<div class="home-heading"><h2>Bank price-target revisions</h2><button id="analystTargetRefresh" ${analystTargetBusy?'disabled':''}>Refresh</button></div><p class="home-caption">${d?.checkedAt?'Checked '+stamp(d.checkedAt)+' · '+esc(d.status||''):analystTargetBusy?'Checking target research…':'First verified update pending'} · Weekdays, 18:00 Paris</p><div class="analyst-target-grid">${rows.slice(0,analystTargetLimit).map(x=>{const p=x.performance||{};return `<article class="analyst-target-card"><header><button data-ticker="${esc(x.ticker)}"><b>${esc(x.ticker)}</b></button><b>${money(x.oldTarget,x.currency)} → ${money(x.newTarget,x.currency)}</b></header><p><b>${esc(x.institution)}</b> · ${esc(x.analyst)}<br>${esc(x.rating)} · Target horizon: ${esc(x.horizon)}</p><div class="analyst-metrics"><span>Target change<b>${num(p.revisionPct)}</b></span><span>Implied upside<b>${num(p.impliedUpside)}</b></span></div><small>${p.latest?'From close '+money(p.latest,x.currency)+' · '+date(p.priceDate):'Current price comparison unavailable'}</small><p>${esc(x.reason)}</p><small>Published ${date(x.published)} · Recorded ${stamp(x.observedAt)}</small><details><summary>Forward result · ${esc(p.state||'Pending')}</summary><p>${p.entry?'Entry '+date(p.entry)+' · '+p.sessions+' sessions · stock '+num(p.returnPct)+' · vs S&P 500 '+(p.excess==null?'—':p.excess.toFixed(2)+' pp'):'No completed closing price after observation yet.'}</p>${p.entry?'<p>Target touched at a close in tracking window: '+(p.targetTouched?'Yes':'Not observed')+'</p>':''}<p>${esc(d.method)}</p></details><footer><button data-map="${esc(x.ticker)}">Map</button>${x.sources.map((u,i)=>researchLink(u,'Source '+(i+1))).join(' · ')}</footer></article>`}).join('')||'<p class="home-caption">No verified target revisions published for this selection yet. Unverified posts are excluded.</p>'}</div>${rows.length>analystTargetLimit?'<button id="analystTargetsMore">Show more revisions</button>':''}<details class="analyst-scorecard"><summary>Institution & analyst track records</summary><p class="home-caption">Forward 20-session outcomes from first observation, not backfilled successes. Directional wins reflect the target’s direction from entry. Minimum 10 completed observations before a descriptive sample; revisions can overlap.</p>${(d?.trackRecords||[]).map(g=>`<div><b>${esc(g.name)}</b><span>${g.completed}/${g.observed} complete · ${esc(g.label)}</span><span>Directional win ${num(g.winRate)} · mean stock return ${num(g.meanReturn)} · vs S&P 500 ${g.meanExcess==null?'—':g.meanExcess.toFixed(2)+' pp'} · target touches ${g.touched}</span></div>`).join('')||'<p>No forward observations yet.</p>'}</details><p class="home-caption">Targets are attributed forecasts, not expected profits. A target change differs from a rating change; implied upside excludes dividends and costs.</p>`;
 host.querySelector('#analystTargetRefresh').onclick=()=>loadAnalystTargets(true);
 const more=host.querySelector('#analystTargetsMore');if(more)more.onclick=()=>{analystTargetLimit+=8;renderAnalystTargets()};
}
async function loadAnalystTargets(force=false){if(analystTargetBusy)return;if(!force&&analystTargetData&&Date.now()-analystTargetChecked<15*60000){renderAnalystTargets();return;}analystTargetBusy=true;renderAnalystTargets();try{analystTargetData=await getLiveJSON('/api/research/analyst-targets');analystTargetChecked=Date.now()}catch{const el=document.querySelector('#analystTargets');if(el)el.innerHTML='<h2>Bank price-target revisions</h2><p>Target feed unavailable. Reopen Research to retry.</p>'}finally{analystTargetBusy=false;if(analystTargetData)renderAnalystTargets()}}
